module bracket_fixer (\n    input clk,\n    input rst_n,\n    input start,\n    input [15:0] seq,\n    input [4:0] valid_length,\n    output reg result,\n    output reg done\n);\n\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] PROCESS = 2'd1;\n    localparam [1:0] DONE_STATE = 2'd2;\n\n    reg [1:0] state;\n    reg [4:0] counter;\n    reg signed [7:0] current_balance;\n    reg signed [7:0] min_balance;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            counter <= 5'd0;\n            current_balance <= 8'd0;\n            min_balance <= 8'd0;\n            result <= 1'b0;\n            done <= 1'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        counter <= 5'd0;\n                        current_balance <= 8'd0;\n                        min_balance <= 8'd0;\n                        if (valid_length == 5'd0)\n                            state <= DONE_STATE;\n                        else\n                            state <= PROCESS;\n                    end\n                end\n\n                PROCESS: begin\n                    if (seq[counter] == 1'b0) begin\n                        current_balance <= current_balance + 8'd1;\n                        if (min_balance > current_balance + 8'd1)\n                            min_balance <= current_balance + 8'd1;\n                    end else begin\n                        current_balance <= current_balance - 8'd1;\n                        if (min_balance > current_balance - 8'd1)\n                            min_balance <= current_balance - 8'd1;\n                    end\n\n                    counter <= counter + 5'd1;\n\n                    if (counter + 5'd1 == valid_length)\n                        state <= DONE_STATE;\n                end\n\n                DONE_STATE: begin\n                    result <= (current_balance == 8'd0) && (min_balance >= -8'd1);\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule